edits.newText:
export function hasPackageTable(toml: string): boolean {
	return /^\[package\]\s*$/m.test(toml);
}

/** A scaffolding template crate: its package name is still a `{{...}}` placeholder, not a real name. */
export function isTemplatePackage(toml: string): boolean {
	const section = toml.split(/^\[package\]\s*$/m)[1] ?? "";
	const name = section.match(/^\s*name\s*=\s*["']([^"']*)["']/m)?.[1];
	if (name !== undefined) return /\{\{.*\}\}/.test(name);
	return /\{\{[^}]*\}\}/.test(section);
}

