for (let dir = dirname(filePath); ; dir = dirname(dir)) {
	const manifest = join(dir, "Cargo.toml");
	if (exists(manifest)) {
		const toml = readFile(manifest);
		if (hasPackageTable(toml)) {
			// A template crate is not a real crate: stop here instead of climbing to the crate around it.
			if (isTemplatePackage(toml)) return undefined;
			return dir;
		}
	}
	if (dirname(dir) === dir) return undefined;
}

